import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import api from "@landinghub/api"; // axios instance
import LeadKanban from "../components/LeadKanban";
import LeadForm from "../components/LeadForm";
import LeadEditModal from "../components/LeadEditModal";

const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [view, setView] = useState("kanban");
  const [draggedLead, setDraggedLead] = useState(null);
  const [editingLead, setEditingLead] = useState(null);

  // 🟢 Lấy danh sách leads
  const fetchLeads = async () => {
    try {
      const res = await api.get("/api/leads");
      const data = Array.isArray(res.data)
        ? res.data
        : Array.isArray(res.data.data)
        ? res.data.data
        : [];
      setLeads(data);
    } catch (err) {
      console.error("Fetch leads error:", err);
      setLeads([
        { _id: "1", name: "Nguyễn Văn A", email: "a@gmail.com", phone: "0901", status: "new" },
        { _id: "2", name: "Trần Thị B", email: "b@gmail.com", phone: "0902", status: "processing" },
        { _id: "3", name: "Phạm C", email: "c@gmail.com", phone: "0903", status: "converted" },
      ]);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, []);

  // 🟢 Tạo lead mới
  const onAdd = async (form) => {
    const newLead = { ...form, status: "new" };
    try {
      const res = await api.post("/api/leads", newLead);
      const data = res.data?.data || res.data;
      setLeads([...leads, data]);
    } catch (err) {
      console.error("Add lead error:", err);
      setLeads([...leads, { ...newLead, _id: Date.now().toString() }]);
    }
  };

  // 🟢 Xóa lead
  const onDelete = async (id) => {
    if (!window.confirm("Xóa lead này?")) return;
    try {
      await api.delete(`/api/leads/${id}`);
    } catch (err) {
      console.error("Delete lead error:", err);
    }
    setLeads((prev) => prev.filter((l) => l._id !== id));
  };

  // 🟢 Kéo thả lead sang cột khác
  const onDragStart = (lead) => setDraggedLead(lead);

  const onDrop = async (newStatus, lead) => {
    if (!lead) return;
    const updatedLead = { ...lead, status: newStatus };

    // Cập nhật UI ngay
    setLeads((prev) =>
      prev.map((l) => (l._id === lead._id ? updatedLead : l))
    );

    try {
      const res = await api.put(`/api/leads/${lead._id}`, updatedLead);
      if (res.data?.success) {
        console.log("✅ Đã lưu trạng thái:", res.data.data.status);
      } else {
        console.warn("⚠️ Server phản hồi lạ:", res.data);
      }
    } catch (err) {
      console.error("❌ PUT lỗi:", err);
      alert("Không thể lưu trạng thái lên server!");
    }
  };

  // 🟢 Lưu chỉnh sửa trong popup
  const handleSaveEdit = async (form) => {
    try {
      const res = await api.put(`/api/leads/${form._id}`, form);
      if (res.data.success) {
        setLeads((prev) =>
          prev.map((l) => (l._id === form._id ? res.data.data : l))
        );
      }
    } catch (err) {
      console.error("❌ Update error:", err);
    }
    setEditingLead(null);
  };

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      {/* Header */}
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-semibold text-gray-700">📊 Quản lý Leads</h2>
        <div className="flex gap-2">
          <button
            onClick={() => setView("kanban")}
            className={`px-4 py-2 rounded ${view === "kanban" ? "bg-blue-600 text-white" : "bg-gray-200"}`}
          >
            🧩 Kanban
          </button>
          <button
            onClick={() => setView("list")}
            className={`px-4 py-2 rounded ${view === "list" ? "bg-blue-600 text-white" : "bg-gray-200"}`}
          >
            📋 Danh sách
          </button>
        </div>
      </div>

      {/* Form tạo lead */}
      <LeadForm onAdd={onAdd} />

      {/* Kanban / List view */}
      {view === "kanban" ? (
        <LeadKanban
        leads={leads}
        onDragStart={onDragStart}
        onDrop={onDrop}
        onDelete={onDelete}
        onUpdate={(newLeads) => setLeads(newLeads)}
        onEdit={(lead) => setEditingLead(lead)} // 🟢 TRUYỀN XUỐNG
      />

      ) : (
        <motion.table layout className="w-full border-collapse bg-white rounded-lg shadow overflow-hidden">
          <thead className="bg-gray-100 text-gray-600">
            <tr>
              <th className="p-3 text-left">Tên</th>
              <th className="p-3 text-left">Email</th>
              <th className="p-3 text-left">Phone</th>
              <th className="p-3 text-left">Trạng thái</th>
              <th className="p-3 text-left">Hành động</th>
            </tr>
          </thead>
          <tbody>
            {leads.map((lead) => (
              <tr key={lead._id} className="border-t hover:bg-gray-50">
                <td className="p-3">{lead.name}</td>
                <td className="p-3">{lead.email}</td>
                <td className="p-3">{lead.phone}</td>
                <td className="p-3">{lead.status}</td>
                <td className="p-3 flex gap-2">
                  <button
                    onClick={() => setEditingLead(lead)}
                    className="text-blue-500 hover:text-blue-700"
                  >
                    ✏️
                  </button>
                  <button
                    onClick={() => onDelete(lead._id)}
                    className="text-red-500 hover:text-red-700"
                  >
                    ✖
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </motion.table>
      )}

      {/* Popup chỉnh sửa lead */}
      {editingLead && (
        <LeadEditModal
          lead={editingLead}
          onClose={() => setEditingLead(null)}
          onSave={handleSaveEdit}
        />
      )}
    </div>
  );
};

export default Leads;
